"Only builders build. No builder selected — the button picks the nearest idle one and starts the blueprint; then LMB on a spot.":"Строи само инженер. Няма избран инженер — бутонът ще избере най-близкия свободен и ще включи чертежа; после ляв бутон на мястото.",
"Pick a power, then click the target":"Избери удар и кликни цел на картата",
"Controls":"Управление",
"All strategy keys":"Всички клавиши за стратегия",
