"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Нов вид на рудата: жилите са светещи изумрудени шлифовани кристали върху черен базалт с искри и зелена омара; екстракторът е шестоъгълен постамент със сотов купол и решетъчна кула със зелен фар (ивицата и флагчето са в цвета на отбора)",
"New in v6.1":"Новото във v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Предпочитан клас като в Battlefield (U, цифри след гибел): появяваш се в него, когато е наличен",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Техника от първо лице (V — отвън/от кабината); лек автоматичен прицел — в Настройките",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Лесно излизане от ядрото: интервал — към шахтата, B — капсула към повърхността; ефектите на способностите се нулират при гибел",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Безкрайно развитие: генерали и Маршал ★, нива на кариерата, майсторство с оръжията и приставки, медали, ежедневни договори — екран „Кариера\"",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Стратегия: плавно мащабиране с колелото, значки и надписи над юнитите (Alt — всички), панел „Войски / Сгради\" вляво",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"ДБ — атака в движение, двоен ДБ — марш със стрелба в движение; редките заповеди — в „Още заповеди ▾\"; без дублиращи се бутони",
"New in v6":"Новото във v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Стрелба като в шутърите: моментални куршуми, автомат 720 изстр./мин, картечница, откат, прицел с ДБ, пълнители и презареждане с R, маркери за попадения",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"По-тежка гравитация, отзивчив джетпак, рязък скок с Z или двоен джетпак във въздуха; оръжието вече не лети след теб при смяна на бойеца",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Инженери: избери инженер, избери сграда, постави чертеж; екстрактори върху рудните жили; клик на „РУДА\" — откъде идва доходът и как да го ускориш",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Сивите бутони обясняват защо и предлагат решение; по-едри бутони, лента „В процес\", „▶ Управлявай\", Tab е единственият клавиш за режим",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Камера на стратегията без скокове и преобръщания, мащаб към курсора, миникартата може да се дърпа",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Нова техника: рейдър „Чакал\", РСЗО „Град\" (самонасочващи се ракети), миномет „Чук\"; Роят получава „Оса\", „Кошер\", „Требюше\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Стратегът пази заповедите и не спами с глас; боевете идват при теб; B — прехвърляне, Shift+B — в схватката; компас, H — коя цел",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Свободна игра (K) и действие сам (J), F2 — пресети; Esc — пауза и обратно; запазвания: слотове, експорт и импорт",
"New in v5.3":"Новото във v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Полет: по-силна гравитация далеч от метеорита, C във въздуха спира, тягата завива по-рязко; вече не се заклещваш в портала",
"New in v5":"Новото във v5",
"Endless war by default and battle scale: normal, large, epic":"Безкрайна война по подразбиране и мащаб на боевете: нормален, голям, епичен",
