"🛠 Developer mode: everything unlocked, endless ore. Arsenal — F8 or the \"🛠 Arsenal\" button.":"🛠 Режим за разработчици: всичко отключено, безкрайна руда. Арсенал — F8 или бутонът „🛠 Арсенал\".",
"Developer mode off (the match stays flagged — career is not saved)":"Режимът за разработчици е изключен (мачът остава маркиран — кариерата не се записва)",
