"CUSTOM POSSESSION ORDER":"СОБСТВЕН РЕД НА КОНТРОЛ",
"Possession — class order":"Контрол — ред на класовете",
"Defence":"Отбрана",
"MG bunker":"Бункер с картечница",
"A concrete pillbox by the outpost: its MG hits infantry and drones within 60 m.":"Бетонен бункер до аванпоста: картечницата удря пехота и дронове на 60 m.",
"Heavy bunker with AT gun":"Тежък бункер с ПТ оръдие",
"A second bunker with an anti-tank gun (vehicles out to 110 m); the pillbox gets armour plates and the outpost +35% HP.":"Втори бункер с противотанково оръдие (техника до 110 m); бункерът с картечницата се обшива с броня, а аванпостът е с 35% по-здрав.",
"Support":"Поддръжка",
"Repair-drone bay":"Хангар за ремонтни дронове",
"Three repair drones fix friendly robots, vehicles and buildings within 28 m.":"Три ремонтни дрона поправят свои роботи, техника и сгради в радиус 28 m.",
"Force-field dome":"Силов купол",
"A 24 m dome: friendlies inside take 38% less damage.":"Купол с радиус 24 m: свои вътре получават с 38% по-малко щети.",
"Recon":"Разузнаване",
"Radio scanner":"Радиоскенер",
"A scanner mast clears the fog of war within 150 m.":"Мачта със скенер премахва мъглата на войната в радиус 150 m.",
"Sniper & spotter tower":"Снайперска кула-коректировчик",
"Vision 190 m, marks enemies for the whole army (160 m), artillery and MLRS are twice as accurate there, and a sniper on top shoots infantry.":"Обзор 190 m, бележи врагове за цялата армия (160 m), артилерията и РСЗО в отбелязания район удрят два пъти по-кучно, а снайперист на кулата стреля по пехота.",
"Armour plating":"Бронеплочи",
"HQ +50% HP and −25% damage taken.":"Щаб +50% здравина и −25% получени щети.",
"Defence turrets":"Защитни кули",
"4 twin turrets on the HQ platform: infantry, drones and light vehicles within 95 m.":"4 сдвоени кули на платформата на щаба: пехота, дронове и лека техника до 95 m.",
"Faster orbital drop":"Ускорено орбитално десантиране",
"A homing beacon: squads and solos from the barracks, builders and the drop pod are 35% faster, the pod is 25% cheaper.":"Насочващ маяк: отряди и единаци от казармата, инженери и десантната капсула са готови с 35% по-бързо, капсулата е с 25% по-евтина.",
"Ore refinery columns":"Колони за обогатяване на руда",
"Income +25%.":"Доход +25%.",
"Global radar":"Глобален радар",
"Every 40 s a pulse reveals every enemy on the meteor for 6 s.":"На всеки 40 s импулс показва всички врагове на метеорита за 6 s.",
"Comms array":"Антени за връзка",
"+2 command points now and +1 more every 40 s (strikes, strategist powers).":"+2 командни точки веднага и още +1 на всеки 40 s (удари, способности на стратега).",
