"Built":"Построено",
"Building — click to cancel (refund)":"Строи се — клик: отмяна (рудата се връща)",
"Outpost upgrades":"Подобрения на аванпоста",
"point":"точка",
"Pick a branch — every point gets its own speciality:":"Избери клон — всяка точка има своя специализация:",
"Building — click to cancel":"Строи се — клик: отмяна",
"A builder near the outpost (30 m) does the upgrade.":"Подобрението го строи инженер до аванпоста (30 m).",
"Send a builder":"Прати инженер",
"Builders nearby":"Инженери наблизо",
"{0} is heading to the outpost":"{0} тръгва към аванпоста",
"From the very start your base has the whole army, one of each: sky troopers, lone heavy gunner, sniper, scout, drone, raider, MLRS, mortar (plus assault squads and a tank) — possess anyone right away":"От самото начало на боя в щаба стои цялата армия по един: десант, тежък картечар единак, снайперист, разузнавач, дрон, „Чакал\", РСЗО, минохвъргачка (и щурмови отряди с танк) — контролирай когото и да е веднага",
"\"Custom order\" for possession (pause menu, ☰ on the phone): each class has a number, 1 is the top; ▲▼ change it, ✕ means never. After death and on X you get the unit closest to the fight in that order":"„Собствен ред\" на контрол (пауза, на телефон ☰): всеки клас има номер, 1 е главният; ▲▼ го сменят, ✕ значи никога. След смърт и при X се взема най-близкият до боя боец по този ред",
"Bots are no longer snipers: they miss at range, on the move, against runners and targets in cover; bullets whizz past you and kick up dirt and cover nearby. Explosions knock you down: flinch, to one knee, off your feet and back up":"Ботовете вече не са снайперисти: пропускат отдалеч, в движение, по бягащи и прикрити цели; покрай теб куршумите свистят, удрят в земята и прикритието наблизо. Експлозиите те събарят: потрепване, на коляно, на земята и пак на крака",
"Capture a point and a pod drops a squad and a builder. An outpost on the point upgrades along one branch: defence (MG bunker → heavy bunker with AT gun), support (repair drones → force-field dome), recon (radio scanner → sniper & spotter tower)":"Завладей точка и капсула пуска отряд и инженер. Аванпостът на точката се развива по един клон: отбрана (бункер с картечница → тежък бункер с ПТ оръдие), поддръжка (ремонтни дронове → силов купол), разузнаване (радиоскенер → снайперска кула)",
"The HQ upgrades too: armour plating, defence turrets, faster orbital drop, +25% income, global radar, comms array (+command points). The AI does the same":"Щабът също се развива: бронеплочи, кули, ускорено орбитално десантиране, доход +25%, глобален радар, антени за връзка (+командни точки). ИИ прави същото",
"New in v7.0":"Ново във v7.0",
"Your base has one of every unit and vehicle: sky troopers, sniper, scout, drone, raider, MLRS, mortar. Select any and {0} — try them before you even build.":"В щаба има по един боец и машина от всеки тип: десант, снайперист, разузнавач, дрон, „Чакал\", РСЗО, минохвъргачка. Избери когото и да е и {0} — пробвай, преди да си построил базата.",
"POSSESS":"КОНТРОЛ",
"Point {0}: a builder landed with the pod. Select it and place an \"Outpost\"{1} by the point — then pick an upgrade branch.":"Точка {0}: от капсулата слезе инженер. Избери го и постави „Аванпост\"{1} до точката — после ще избереш клон на подобрения.",
"OUTPOST":"АВАНПОСТ",
"The outpost is ready — select it and pick a branch: ⛨ Defence (MG bunker, AT bunker), ✚ Support (repair drones, force-field dome) or ◎ Recon (scanner, sniper tower). A builder nearby does the work.":"Аванпостът е готов — избери го и вземи клон: ⛨ Отбрана (бункер с картечница, бункер с ПТ оръдие), ✚ Поддръжка (ремонтни дронове, силов купол) или ◎ Разузнаване (скенер, снайперска кула). Строи инженер наблизо.",
"UPGRADE":"ПОДОБРИ",
"The HQ is a \"super point\": select it{0} — armour, turrets, faster drops, +25% income, radar, comms.":"Щабът е „супер-точка\": избери го{0} — бронеплочи, кули, ускорено десантиране, доход +25%, радар, антени за връзка.",
"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"☰ → „Контрол\": включи „Собствен ред\" и реши кого да контролираш след смърт — №1, №2… ✕ значи никога.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"Esc → пауза → „Собствен ред\": реши кого да контролираш след смърт и при X — №1, №2… ✕ значи никога.",
