"building ":"строеж ",
"what to build?":"какво да се строи?",
"under construction":"в строеж",
"what to produce?":"какво да се произвежда?",
"Pick an engineer or a building on the left":"Избери строител или сграда отляво",
"Strategy: simple (engineer & buildings)":"Стратегия: проста (строител и сгради)",
"Possession: ":"Овладяване: ",
"squads":"отряди",
"vehicles":"техника",
" · AI drives vehicles, E next to one — man its gun":" · ИИ кара техниката, E до машина — седни зад оръдието",
"Possess squads (infantry)":"Овладявай отряди (пехота)",
"Possess vehicles and drones":"Овладявай техника и дронове",
"On the gun: {0}. The AI drives, you shoot. {1} — get off":"Зад оръдието: {0}. ИИ кара, ти стреляш. {1} — слез",
"The vehicle is destroyed — you jumped off":"Машината е унищожена — ти скочи",
"{0} — get off the gun":"{0} — слез от оръдието",
"{0} — man the gun: {1}":"{0} — седни зад оръдието: {1}",
"Combo ×{0} · reflex +{1}%":"Комбо ×{0} · рефлекс +{1}%",
"Strategist: troopers dropping to you — +{0} (−{1} ore)":"Стратег: десант при теб — +{0} бойци (−{1} руда)",
"Hold on, sending troopers your way":"Дръж се, изпращам ти десант",
"· basic{0}":"· основни{0}",
"· advanced":"· разширени",
"· rare":"· редки",
"Advanced: class order":"Разширени: ред на класовете",
"Voice of hints and curator":"Глас на подсказките и Наставника",
"Advanced: custom class order":"Разширени: собствен ред на класовете",
"Voice of hints & curator":"Глас на подсказките и Наставника",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Телефон: три режима на джойстиците. Само левият — „авто\" (силен магнит, по-слаби куршуми). Само десният — мерникът се включва сам, магнитът е по-силен, стрелбата — по-точна. И двата — без мерник, магнитът и точността са по-малки. Бутонът 👁 отдясно скрива/връща интерфейса.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Телефон: стратегията е опростена — само строител и сгради. Карти отляво (строител, Щаб, Казарма…): докосване — камерата отива там, долу веднага се вижда какво да строиш/произвеждаш. „В бой\" — горе вляво. Армията воюва сама. Пълна стратегия — Настройки → Телефон.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Овладяване — два превключвателя: „Отряди\" и „Техника\" (на телефон техниката е изключена по подразбиране — карае я ИИ). Ако техниката е изключена, E (на телефон — бутонът вдясно) до своя машина — седни зад оръдието ѝ: машината се движи сама, ти стреляш. Старият „собствен ред на класовете\" е в „Разширени\". При овладяване юнитът отговаря по радиото.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Умни подсказки: основните сами изгасват след 2-рия старт, но играта ще ти подскаже функция, която така и не използваш. Превключватели: основни / разширени / редки, отделно — гласът на подсказките и Наставника.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Съотрядниците изостанат или загинат — стратегът ти десантира нови (по-скъпо от обичайното подкрепление). Графиката и звукът от v7.2gfx са включени: взривове на кълба, дим, отломки, акустика на шахти и кратери. Датата на билда вече е истинска.",
