"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Кариерата и записите не се променят. В боя същото меню е бутонът „🛠 Меню\" горе вдясно{0}.",
"New developer match":"Нов мач за разработчик",
"all unlocked, endless ore, instant build, arsenal":"всичко отключено, безкрайна руда, мигновен строеж, арсенал",
"Trainings — all 4":"Обучения — всичките 4",
"PC and phone (strategy and shooter)":"ПК и телефон (стратегия и Стрелец)",
"Cinema: split screen":"Кино: разделен екран",
"strategist bot left, shooter bot right":"вляво бот-стратег, вдясно бот-стрелец",
"Cinema: everything built":"Кино: всичко е построено",
"both bases built and upgraded — for footage":"двете бази са построени и подобрени — за заснемане",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Кино режим — разделен екран: вляво бот-стратег (изглед отгоре към базата и армията), вдясно бот-стрелец от първо лице. Бутони долу (и клавиши S, P): „Разделен екран\" и „★ Всичко е построено\" — двете бази са построени и подобрени за заснемане.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Ядрото и тунелите през метеорита вече ги няма — метеоритът е плътен, боят е само на повърхността.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Телефон: 👁 скрива интерфейса, но оставя джетпака, ⇆, стиковете и маркера на задачата. „◎ Прицел\" (само с десния пръст) — осезаемо по-силен и по-широк магнит; силата на магнита за трите режима — Настройки → Управление → „Разширени\". На оръдие на машина бутонът се казва „Слез\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Обучение: на телефон — само телефонните, на ПК — само ПК. И четирите са в менюто „🛠 Разработчик\". Режимът за разработчици и Арсеналът са обединени в едно меню (в боя — „🛠 Меню\" горе вдясно, на ПК още и F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Стилове графика „Dendy (8-бит)\" и „16-бит\": Настройки → Графика → „Стил на графиката\" (подробности — бутонът ⚙). Ако през първите ~10 s от мача FPS е под 24, Dendy се включва сам (под 20 и нататък — още по-едър пиксел, 120 реда); бележката „върни обичайната\" връща нормалната графика завинаги. Твоят избор в менюто винаги има предимство.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D модели на околната среда (руини, техника, укрепления) — само добре оценените, зареждат се при нужда от интернет. Изключване: Настройки → Графика → „Нови 3D модели на околната среда\".",
