"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Строеж от войници: E (на телефон „Влез\") при свой строеж — войникът строи сам, съседите от отряда помагат. Ако инженерите са заети, стратегът сам ще те помоли за помощ — маркер „СТРОЕЖ\".",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Маркери на стратега: стратегът поставя ⌖ върху струпване на врагове до теб — след 8 s там удря артилерията, а наши РСЗО „Град\" наблизо дават залп. Твоят артилерийски удар от режима Стратег също получава подкрепа от „Градове\".",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Скривалища с оръжие в товарни контейнери и паднали спътници (📦 се вижда от 70 m): E — тежка картечница за 90 s, запалителни патрони или ракети, плюс пълни гранати. Пълзене: Ctrl — легни / стани (по-ниско, по-тихо, по-точно, но бавно).",
