"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Попаденията се усещат: метален звук и искри, маркер за убийство до мерника (в главата — жълт), серия ×N, плавно тресене от взривове, бавно движение при важни убийства. Тресенето, бавното движение и подсказката могат да се изключат в Настройките.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Резултат от мача: време, унищожени, най-добра серия, ★ MVP и най-добър отряд, карта на мача — „⇪ Сподели\", PNG или линк към играта.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Подсказка „какво да правя сега\" отляво под ресурсите: заповедта на стратега, точка за завладяване, настъпление на Роя. ✕ или F7 — свий.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Боят се запазва сам, ако затвориш или скриеш раздела — „⟲ Продължи\" в менюто.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Версия v7.5 остава в менюто „🕘 Версия на играта\" — ако новата не ти хареса. Вече се изпраща анонимна статистика (без имена и имейли); изключване — в Настройките.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"„Играй сега\", отклик при попадения, резултат от мача с карта, подсказка „какво да правя\", автозапис",
"and older: v7.5, v7.4, milestones v1–v7.0":"и по-стари: v7.5, v7.4, етапи v1–v7.0",
"New in v7.6":"Ново във v7.6",
"NEW IN v7.6":"НОВО ВЪВ v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Избор на фракция преди мач: „Консорциум\" (тежка пехота в силова броня, бронетехника и артилерия) или „Роят\" (скорост, ята дронове, тежки изстрели с изкривяване). ИИ играе с другата. Изборът се запомня.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Всяка фракция има своя техника и уникални неща: Консорциумът — танк „Носорог\" и „Керамитни плочи\", Роят — „Ято дронове\" и „Фазови реактивни раници\". Балансът е проверен с мачове на ботове.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Кратери от взривове: артилерията, ракетите и оръдията на танковете ровят ями в метеорита — по тях се ходи и се кара, а вътре можеш да се скриеш.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Изглед от трето лице за бойеца (V, запомня се; на телефон — Управление) и плавна камера за техниката с маркер къде ще удари оръдието.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Версия v7.6 остана в менюто „🕘 Версия на играта\" — ако новата не ти хареса.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Фракции Консорциум / Роят с избор преди мача, кратери от взривове, изглед от трето лице",
"and older: v7.6, v7.5, milestones v1–v7.0":"и по-стари: v7.6, v7.5, етапи v1–v7.0",
