"Anomaly ahead! The vein is singing — go around!":"Аномалия напред! Жилата пее — заобикаляме!",
"Hear that hum? A singing vein. Keep clear!":"Чувате ли това бръмчене? Пееща жила. Не се приближавайте!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Аномалия! Въздухът се върти — това е водовъртеж, заобиколи!",
"Rocks floating in the air… A whirlpool! Stay out!":"Камъни висят във въздуха… Водовъртеж! Не се пъхай!",
"Anomaly ahead — it is crackling with current!":"Аномалия напред — пука от ток!",
"Rods and lightning — a Crackler. It loves armour!":"Шипове и мълнии — Пукач. Обича бронята!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Аномалия! Земята трепти от жега — Жарава!",
"Careful, a Brazier underfoot!":"Внимателно, под краката ти има Жарава!",
"Anomaly — green mist! Acid, hold your breath!":"Аномалия — зелена мъгла! Киселина, не дишаме!",
"The mist is drifting our way, go around!":"Мъглата пълзи към нас, заобикаляме!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Аномалия! Въздухът е като стъкло — Леща, огъва куршумите!",
"Everything is warping… a Lens nearby!":"Всичко се изкривява… Леща наблизо!",
"Ha! An enemy walked right into the anomaly!":"Ха! Врагът влезе право в аномалията!",
"Got him! Lure them into anomalies!":"Улучих го! Примамвай ги в аномалиите!",
"Beautiful zap! One less tin can.":"Красиво гръмна! Минус една ламарина.",
"The anomaly got me!":"Аномалията ме закачи!",
"Ow! Don't go in there!":"Ох! Не влизайте там!",
"Discharged! It is dormant now.":"Разредих я! Сега спи.",
"Clear, the anomaly is discharged.":"Чисто, аномалията е разредена.",
"They say veins hide artifacts. Only first the vein sings…":"Казват, че в жилите се крият артефакти. Само че първо жилата пее…",
"Throw a bolt first, then walk. Old habit.":"Първо хвърли болт, после върви. Стар навик.",
