"Restart":"Започни отначало",
"Shooter":"OK_SKIP",
"The Commander mode is not in the game yet":"Режим „Командир\" още го няма в играта",
"Commander · soon":"Командир · скоро",
"Commander — still in development":"Командир — още в разработка",
"Pause: resume, restart, training, graphics, settings, main menu":"Пауза: продължи, отначало, обучение, графика, настройки, главно меню",
"Menu: pause, restart, training, graphics, settings":"Меню: пауза, отначало, обучение, графика, настройки",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Дръж пръста на земята ~0,3 с — телефонът ще трепне и ще се появи жълт пръстен — и, без да вдигаш, влачи: ще се получи рамка. Или бутонът „Рамка\" вдясно. Може и просто да докоснеш отряд.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"За цял екран на iPhone: „Сподели\" ⬆ → „Добави към началния екран\" — играта ще се отвори без лентите на Safari.",
"Open portal-meteor.pages.dev for that.":"За целта отвори сайта portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Докосване — избор · докосване по земята — ход · дръж — меню с команди · дръж и влачи — рамка · 2 пръста — мащаб",
"Robo-ninja":"Робо-ниндзя",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Героиня-убиец: рязки телепортиращи скокове, катана, шурикени. Сама скача по зоните на врага и реже роботи. 1 на страна.",
"Shadow protocol":"Протокол „Сянка\"",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Изследване: отключва робо-нинджа в Казармата. Нужна е готова фабрика за мехове.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Герой (1 на страна): сама се телепортира по зоните на врага и реже роботи; можеш да я овладееш и да играеш ръчно.",
"is ready. She works on her own (AUTO) — possess her to play manually":"е готова. Работи сама (АВТО) — овладей я, за да играеш ръчно",
"Robo-ninja ready for action":"Робо-нинджа е готова за бой",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Разузнаване: противникът има робо-нинджа!",
"Warning! The enemy has a robo-ninja. Stay together":"Внимание! Противникът има робо-нинджа. Дръжте се заедно",
"cyber blinks":"кибер-скокове",
"Too far for a dash — get closer or teleport":"Далеч за скок — приближи се или телепорт",
"point ":"точка ",
"enemy group":"група на врага",
"order":"заповед",
"nearby":"наблизо",
"Zone cleared":"Зоната е зачистена",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ ДУЕЛ НА НИНДЖИ! Блок точно преди удар — парирване, скок — отбягване. Следи светкавицата на замаха",
"The two ninjas have met in a duel!":"Двете нинджи се срещнаха в дуел!",
"⚔ Duel won! Our ninja prevails":"⚔ Дуелът е спечелен! Нашата нинджа е по-силна",
"⚔ Duel lost…":"⚔ Дуелът е загубен…",
"ninja duel":"дуел на нинджи",
"POSTURE BROKEN":"СТОЙКАТА Е СЧУПЕНА",
"Teleport":"Телепорт",
"Teleport: aim at the ground (up to 150 m)":"Телепорт: насочи мерника към земята (до 150 м)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ АВТО: сама скача по зоните на врага и реже. Джойстик / WASD — пауза 1.5 с",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Ръчно: докосване по враг — скок и удар, плъзгане — замах, 🛡 — блок",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Ръчно управление: ляв бутон — катана, десен бутон — блок, Shift — скок, Q — шурикени, G — телепорт",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Нинджа: докосване по враг — рязко приближаване и удар, плъзгане отдясно — замах, ● — удар, 🛡 — блок (навреме = париране), ⇑ — скок напред, ✦ — шурикени, ◎ — телепорт, АВТО — сама",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Нинджа: ляв бутон — катана (задръж — тежък удар), десен бутон — блок (навреме = париране), Shift/Z — скок напред, Q — шурикени, G — телепорт към мерника, скок във въздуха — двоен скок / бягане по стена, {0} — АВТО",
