"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Радио Portal Meteor: 100+ трека на EDMITRY направо в играта — бутонът 📻 (ПК: клавиш 5, [ ] — трек). Музиката се зарежда онлайн и не натоварва играта; сила на звука и автостарт в Настройки, плюс връзка „Слушай в Spotify“.",
