"Radio Portal Meteor (EDMITRY): volume":"Радио Portal Meteor (EDMITRY): сила на звука",
"Radio: start by itself in battle":"Радио: да се включва само в битка",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Робо-нинджа: киборг с катана. Отключва се в Казармата с изследването „Протокол „Сянка““ (трябва фабрика за мехове). Сама се телепортира във вражески зони, разсича враговете (без кръв — искри), прави скокове напред, хвърля шурикени, дуелира се с вражеския нинджа. Овладей я — режим АВТО или ръчно управление (на телефон — собствени бутони).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Радио Portal Meteor: 103 трека на EDMITRY направо в играта. Клавиш 5 (сменя се), на телефон — ☰ → Настройки → Звук. Силата на звука и „да се включва само в битка“ са в настройките; музиката заглъхва при взривове и под гласа по радиото.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Нови езици: узбекски и таджикски — изцяло; китайски, испански, португалски — частично. Нов избор на език в менюто до „Нов мач“.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Телефон: „скрий иконите“ 👁 събира останалите бутони в подредена колона до десния ръб; портретният режим вече не се застъпва; iPhone — играта не се бори с жестовете на Safari, а „Сподели → Добави към началния екран“ я стартира на цял екран.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"От v7.8.1: ъглово меню ☰ (пауза, отначало, обучение, графика), без авто-Dendy, бутон за действие ✋ на телефон. v7.8.1 и v7.8 остават в менюто „🕘 Версия на играта“.",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"Робо-нинджа, радио EDMITRY, узбекски и таджикски, удобство за телефон и iPhone",
