"Enemy cluster — {0}: strike at your aim":"Струпване на врагове — {0}: удар в мерника",
"Goal: destroy the enemy HQ and all its key buildings":"Цел: разруши вражеския щаб и всички негови ключови сгради",
"60 minutes: destroy the enemy HQ or hold more points":"60 минути: разруши вражеския щаб или дръж повече точки",
"Left thumb — move, right — look, red — fire":"Левият палец — движение, десният — оглед, червеният — огън",
"Mode button at the top right: tap — next, hold — pick":"Бутонът за режима горе вдясно: докосване — следващ, задръжка — избор",
"⇆ — next unit · ☰ — menu, clean screen, this card":"⇆ — смени бойеца · ☰ — меню, чист екран, тази справка",
