"Commander, their AA radar blinds our air. Take it down.":"Командире, радарът на тяхната ПВО заслепява авиацията ни. Събори го.",
"Bring me a crystal from the Singing Vein — I will build something.":"Донеси ми кристал от Пеещата вена — ще сглобя нещо.",
"Our pilot is down, {0}. Get him out.":"Свалиха нашия пилот, {0}. Измъкни го.",
"Destroy the enemy AA radar":"Унищожи вражеския радар на ПВО",
