"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Своите искат помощ и те възнаграждават, героите дават куестове, а проточил се фронт се пробива с операция",
"A request":"Молба на своите",
"Breakthrough":"Прелом в боя",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Своите понякога искат помощ: глас по радиото, карта „МОЛБА\" и маркер ✋. Отряд е притиснат — унищожи враговете край него. Награда: боец с капсула от базата, оръжие от багажника на бъги, място на стрелец или прикритие от орбита. Не искаш — ✕ или просто игнорирай.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Ветеранът разузнавач „Бухал\" предлага куест. Y — приеми (N — откажи). Иди до маркера ★, махни охраната и постой при пилота 3 s — той ще влезе в отряда ти.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Фронтът е заседнал — щабът предлага прелом. Y — приеми. Дръж ретранслатора 8 s без врагове наблизо: вражеската карта се вижда 60 s. Генераторът — вражеските кули мълчат 2 мин. В режим Стратег — „Възложи на отряд\". Врагът също го умее: следи ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Своите искат помощ: карта „МОЛБА\" и маркер ✋. Унищожи враговете край притиснатия отряд — получаваш награда. ✕ — пропусни.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Героят „Бухал\" предлага куест — докосни „Приеми\". Иди до ★, махни охраната, постой при пилота.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Фронтът е заседнал — докосни „Приеми\" и дръж ретранслатора 8 s: вражеската карта ще се отвори за минута.",
