"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Основен боен танк: оръдие и картечница. При Консорциума е „Булдог\" (по-здрав), при Роя — „Паяк\" (по-бърз).",
"Heavy tank":"Тежък танк",
