"Upgrade":"Подобрение",
"Longer, faster jetpacks for all infantry.":"По-дълги и по-бързи джетпаци за цялата пехота.",
"Extractors mine more ore.":"Екстракторите добиват повече руда.",
"Army-wide levels: less damage taken / more damage dealt.":"Нива за цялата армия: по-малко щети по своите / повече щети по врага.",
"Levels":"Нива",
"Base":"База",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Сърцето на базата: отряди, инженери, капсули, изследвания. Загубиш ли го, губиш играта.",
"Produces: ":"Произвежда: ",
"Launch pad":"Стартова площадка",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Шахта до Щаба: оттук излитат капсули, сандъци със снабдяване и бомбардировачи — през небесния портал към целта. Върху нея не се строи.",
"Economy":"Икономика",
"Key building":"Ключова сграда",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Слабо място — кърмата (двигателят): щети ×{0}. Оръдие, 2 картечни кули, ракетна касета; върти се много бавно — заобикаляйте отстрани.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Слабо място — светещото ядро отдолу: щети отдолу ×{0}. Лъч на изкривяването и тропот по площ; прекрачва преградите — пазете дистанция, не се трупайте.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Срещу него: авиобомби и артилерия (×{0}), ракети (×{1}), килимено бомбардиране; куршумите почти не го чупят (×{2}).",
"Faction":"Фракция",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Бързи машини, ята дронове, тунели и регенерация. Пехотата е по-лека, но по-бърза; оръдията и релсите удрят по-силно.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Тежка пехота в силова броня, бетонни прегради, ремонт и артилерия. По-бавни, но по-здрави.",
