"Discharge: an explosion or a thrown bolt (E / \"Bolt\") — it sleeps 20–35 s, sometimes leaves an artifact.":"Разреди: взрив или хвърлен болт (E / „Болт\") — заспива за 20–35 s, понякога оставя артефакт.",
